#!/usr/bin/env bash
# QR code login through the desktop client's frontend, driven by dsb.
# The login page's "扫码登录" shows a QR code generated by the server ({"type":"login","qrId":...}) and polls
# its status every 2 seconds. The phone side is simulated with curl, as the mobile client does it with
# its own session: scan (POST oauth/qrcode/scan), then confirm (POST oauth/qrcode/confirm). The page
# shows "扫码成功，等待授权" after the scan and logs in by itself after the confirmation.
# Usage: scripts/client-qrlogin-e2e.sh [output-dir]   (run with docker access, e.g. sg docker -c ...)
cd "$(dirname "$0")"; set -eo pipefail
OUT=$(mkdir -p "${1:-client-e2e-out}" && cd "${1:-client-e2e-out}" && pwd)
source ./lib.sh
source ./client-lib.sh
task dsb_a "${A_ID:-4341}"

read EA UA EB UB < <(./make-friends.sh | tail -1)
NB=${EB%@*}
# alice's phone session
read TM _ < <(login_user "$EA" MOBILE m1)
echo "alice=$EA"

dsb_a close >/dev/null 2>&1 || true
dsb_a start --browser chrome --headless
dsb_a run set_viewport -p width=1100 -p height=760
dsb_a run go_to_url -p "url=$A_URL/login"
dsb_a js "(() => { localStorage.clear(); sessionStorage.clear(); window.name = ''; return 1 })()"
dsb_a run go_to_url -p "url=$A_URL/login"
dsb_a run wait_for_element -p selector=.driver-popover-next-btn -p timeoutMs=20000
for i in 1 2 3 4; do
  dsb_a run click_element_by_selector -p selector=.driver-popover-next-btn
  sleep 0.6
done

# The QR code is valid for 30 seconds; open it with a plain DOM click (the page keeps polling,
# so waiting for the page to settle would let the code expire) and click the code to refresh it.
QR_JS="(() => { let c = document.querySelector('canvas')?.__vueParentComponent; while (c && !(c.setupState && c.setupState.qrCodeResp)) c = c.parent; return c ? c.setupState.qrCodeValue : '' })()"
dsb_a js "(() => { [...document.querySelectorAll('*')].find(e => e.childElementCount === 0 && e.textContent.trim() === '扫码登录').click(); return 1 })()"
dsb_a run wait_for_element -p selector=canvas -p timeoutMs=10000
dsb_a js "(() => { document.querySelector('canvas').click(); return 1 })()"
wait_text dsb_a 扫码登录
for i in $(seq 1 20); do
  QR_VALUE=$(dsb --id "${A_ID:-4341}" js "$QR_JS" --select data.result 2>/dev/null | python3 -c "import sys, json; print(json.loads(sys.stdin.read() or '\"\"'))" || true)
  [ -n "$QR_VALUE" ] && break
  sleep 0.5
done
echo "QR code content: $QR_VALUE"
QR_ID=$(echo "$QR_VALUE" | json "d['qrId'] if d['type'] == 'login' else ''")
shot dsb_a 51-qr-code.png

# the phone scans: the page switches to "waiting for authorization"
api POST /api/oauth/qrcode/scan "$TM" "{\"qrId\":\"$QR_ID\"}" | json "d['code']" | grep -qx 200
wait_text dsb_a 扫码成功，等待授权
shot dsb_a 52-qr-scanned.png

# the phone confirms: the page receives a token from the status query and logs in
api POST /api/oauth/qrcode/confirm "$TM" "{\"qrId\":\"$QR_ID\"}" | json "d['code']" | grep -qx 200
dsb_a run wait_for_url -p "url=**/message" -p timeoutMs=20000
wait_ready dsb_a "$NB"
shot dsb_a 53-qr-logged-in.png

# the session works: send a message to bob
open_chat dsb_a "$NB"
send dsb_a "这条消息来自扫码登录的会话"
wait_text dsb_a 这条消息来自扫码登录的会话
read TB2 _ < <(login_user "$EB" MOBILE m2)
RID=$(api GET "/api/im/chat/contact/detail/friend?id=$UA&roomType=2" "$TB2" | json "d['data']['roomId']")
api GET "/api/im/chat/msg/page?roomId=$RID&pageSize=5" "$TB2" | json "[m['message']['body'].get('content') for m in d['data']['list'] if m['message']['type'] == 1]" \
  | grep -q 这条消息来自扫码登录的会话

# a used QR code cannot be confirmed again
api POST /api/oauth/qrcode/confirm "$TM" "{\"qrId\":\"$QR_ID\"}" | json "d['code']" | grep -vqx 200

finish dsb_a
ls -la "$OUT"
